type CacheEntry<T> = { value: T; expiresAt: number };

// Shared store so all Cache instances (including ones created by callers)
// see the same keys and are collectively invalidated.
const sharedStore = new Map<string, CacheEntry<unknown>>();

export class Cache {
  private prefix: string;

  constructor(prefix = '') {
    this.prefix = prefix;
  }

  private fullKey(key: string): string {
    return this.prefix ? `${this.prefix}:${key}` : key;
  }

  set<T>(key: string, value: T, ttlMs: number): void {
    sharedStore.set(this.fullKey(key), { value, expiresAt: Date.now() + ttlMs });
  }

  get<T>(key: string): T | null {
    const entry = sharedStore.get(this.fullKey(key));
    if (!entry) return null;
    if (Date.now() > entry.expiresAt) {
      sharedStore.delete(this.fullKey(key));
      return null;
    }
    return entry.value as T;
  }

  invalidate(key: string): void {
    sharedStore.delete(this.fullKey(key));
  }
}
